"""specs_s200040.py - Sonnet-w2 family R (generated by mkfamR.py): 0x45c4f0 / 0x45c4b0 / INIT record the SEH chain; b is zero about half of the cases; the allocators return 0 sometimes
and otherwise a random-filled heap object (so the vtable store and the cleared field are observable). Fake outer SEH records 0-2; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, clear_hooks, hook_rec, seh_record, seh_chain


def _mk(init):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        p = r.choice([0, rnd(c, 0x80), rnd(c, 0x80), rnd(c, 0x80)])
        hook_rec(c, 0x45c4f0, 2, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, 0x45c4b0, 1, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, init, 3, ret=r.getrandbits(32), pop=12, this=True, side=seh_record(c, 2))
        return [r.getrandbits(32), r.getrandbits(32), r.getrandbits(32), r.choice([0, 0, 1, r.getrandbits(32)])]
    return gen


S(0x4f3c80, 'GUESS famR 0x4f3c80', 'fastcall', None, ret='eax', gen=_mk(0x4ee210), note='batch200040')
S(0x4546b0, 'GUESS famR 0x4546b0', 'fastcall', None, ret='eax', gen=_mk(0x43e990), note='batch200040')
S(0x47f810, 'GUESS famR 0x47f810', 'fastcall', None, ret='eax', gen=_mk(0x43de40), note='batch200040')
S(0x4ee740, 'GUESS famR 0x4ee740', 'fastcall', None, ret='eax', gen=_mk(0x43e990), note='batch200040')
S(0x5a5a80, 'GUESS famR 0x5a5a80', 'fastcall', None, ret='eax', gen=_mk(0x43de40), note='batch200040')
